# ============================================================
# 06_Maize_Model_Training.ipynb
# CELL 1 — ENVIRONMENT SETUP + DATASET VERIFICATION
# ============================================================

import os
import random
from pathlib import Path

import numpy as np
import torch
import torchvision

from google.colab import drive

# ------------------------------------------------------------
# 1. Mount Google Drive
# ------------------------------------------------------------

drive.mount("/content/drive")

# ------------------------------------------------------------
# 2. Reproducibility
# ------------------------------------------------------------

SEED = 42

random.seed(SEED)
np.random.seed(SEED)

torch.manual_seed(SEED)

if torch.cuda.is_available():
    torch.cuda.manual_seed(SEED)
    torch.cuda.manual_seed_all(SEED)

# Reproducibility settings
torch.backends.cudnn.deterministic = True
torch.backends.cudnn.benchmark = False

# ------------------------------------------------------------
# 3. Device
# ------------------------------------------------------------

DEVICE = torch.device(
    "cuda" if torch.cuda.is_available()
    else "cpu"
)

# ------------------------------------------------------------
# 4. Frozen dataset path
# ------------------------------------------------------------

DATASET_ROOT = Path(
    "/content/drive/MyDrive/"
    "final_year_project/maize/"
    "Final_Maize_Dataset"
)

TRAIN_DIR = DATASET_ROOT / "train"
VAL_DIR   = DATASET_ROOT / "val"
TEST_DIR  = DATASET_ROOT / "test"

CLASSES = [
    "Healthy",
    "MLN",
    "MSV",
    "NLB",
    "NLS"
]

EXPECTED_COUNTS = {
    "train": {
        "Healthy": 1662,
        "MLN": 1671,
        "MSV": 1709,
        "NLB": 341,
        "NLS": 379,
    },
    "val": {
        "Healthy": 357,
        "MLN": 359,
        "MSV": 367,
        "NLB": 74,
        "NLS": 82,
    },
    "test": {
        "Healthy": 357,
        "MLN": 358,
        "MSV": 367,
        "NLB": 74,
        "NLS": 82,
    }
}

IMAGE_EXTENSIONS = {
    ".jpg", ".jpeg", ".png",
    ".JPG", ".JPEG", ".PNG"
}

# ------------------------------------------------------------
# 5. Basic environment information
# ------------------------------------------------------------

print("=" * 80)
print("MAIZE MODEL TRAINING — ENVIRONMENT SETUP")
print("=" * 80)

print(f"\nPyTorch     : {torch.__version__}")
print(f"Torchvision : {torchvision.__version__}")
print(f"Device      : {DEVICE}")

if torch.cuda.is_available():

    print(
        f"GPU         : "
        f"{torch.cuda.get_device_name(0)}"
    )

    gpu_memory = (
        torch.cuda.get_device_properties(0)
        .total_memory
        / (1024 ** 3)
    )

    print(
        f"GPU memory  : "
        f"{gpu_memory:.2f} GB"
    )

else:

    print(
        "WARNING: GPU is NOT enabled."
    )

# ------------------------------------------------------------
# 6. Verify frozen dataset
# ------------------------------------------------------------

print("\n" + "=" * 80)
print("FROZEN DATASET VERIFICATION")
print("=" * 80)

assert DATASET_ROOT.exists(), (
    f"Dataset not found:\n{DATASET_ROOT}"
)

grand_total = 0

split_paths = {
    "train": TRAIN_DIR,
    "val": VAL_DIR,
    "test": TEST_DIR
}

for split_name, split_dir in split_paths.items():

    assert split_dir.exists(), (
        f"Missing split folder:\n{split_dir}"
    )

    print(f"\n{split_name.upper()}")

    split_total = 0

    for class_name in CLASSES:

        class_dir = (
            split_dir / class_name
        )

        assert class_dir.exists(), (
            f"Missing class folder:\n{class_dir}"
        )

        count = sum(
            1
            for p in class_dir.iterdir()
            if p.is_file()
            and p.suffix in IMAGE_EXTENSIONS
        )

        expected = (
            EXPECTED_COUNTS
            [split_name]
            [class_name]
        )

        assert count == expected, (
            f"Count mismatch for "
            f"{split_name}/{class_name}: "
            f"expected {expected}, "
            f"found {count}"
        )

        print(
            f"  ✓ {class_name:<8}: "
            f"{count:,}"
        )

        split_total += count

    print(
        f"  {'TOTAL':<10}: "
        f"{split_total:,}"
    )

    grand_total += split_total

# ------------------------------------------------------------
# 7. Final verification
# ------------------------------------------------------------

assert grand_total == 8239

print("\n" + "=" * 80)
print("SETUP COMPLETE")
print("=" * 80)

print(
    f"\nTotal frozen images : "
    f"{grand_total:,}"
)

print(
    f"Classes             : "
    f"{len(CLASSES)}"
)

print(
    f"Random seed         : "
    f"{SEED}"
)

print(
    f"Dataset             : "
    f"{DATASET_ROOT}"
)

print(
    "\n✓ Frozen train/val/test dataset verified."
)

print(
    "✓ No split was regenerated."
)

print(
    "✓ No image was modified."
)

print(
    "✓ Ready to build the training pipeline."
)

