# ============================================================
# CELL 2 — MAIZE DATA PIPELINE
# Strong augmentation + ImageFolder + class balancing
# ============================================================

import random
import numpy as np
import torch

from pathlib import Path
from torchvision import datasets, transforms
from torch.utils.data import DataLoader, WeightedRandomSampler

# ------------------------------------------------------------
# Reproducibility
# ------------------------------------------------------------

SEED = 42

random.seed(SEED)
np.random.seed(SEED)
torch.manual_seed(SEED)

if torch.cuda.is_available():
    torch.cuda.manual_seed_all(SEED)

# ------------------------------------------------------------
# Dataset paths
# ------------------------------------------------------------

DATASET_ROOT = Path("/content/Final_Maize_Dataset")

TRAIN_DIR = DATASET_ROOT / "train"
VAL_DIR   = DATASET_ROOT / "val"
TEST_DIR  = DATASET_ROOT / "test"

assert TRAIN_DIR.exists()
assert VAL_DIR.exists()
assert TEST_DIR.exists()

# ------------------------------------------------------------
# Configuration
# ------------------------------------------------------------

IMAGE_SIZE = 256
BATCH_SIZE = 32

NUM_WORKERS = 2

IMAGENET_MEAN = [0.485, 0.456, 0.406]
IMAGENET_STD  = [0.229, 0.224, 0.225]

# ============================================================
# TRAINING AUGMENTATION
# ============================================================
#
# Strong but disease-safe augmentation.
#
# We want robustness to:
# - camera angle
# - framing
# - scale
# - lighting
# - field orientation
#
# But we DON'T want transformations that destroy
# lesion morphology.
# ============================================================

train_transform = transforms.Compose([

    transforms.RandomResizedCrop(
        IMAGE_SIZE,
        scale=(0.70, 1.0),
        ratio=(0.80, 1.20)
    ),

    transforms.RandomHorizontalFlip(
        p=0.5
    ),

    transforms.RandomVerticalFlip(
        p=0.20
    ),

    transforms.RandomRotation(
        degrees=20
    ),

    transforms.RandomApply(
        [
            transforms.ColorJitter(
                brightness=0.25,
                contrast=0.25,
                saturation=0.20,
                hue=0.03
            )
        ],
        p=0.70
    ),

    transforms.RandomApply(
        [
            transforms.GaussianBlur(
                kernel_size=3,
                sigma=(0.1, 1.2)
            )
        ],
        p=0.15
    ),

    transforms.ToTensor(),

    transforms.Normalize(
        mean=IMAGENET_MEAN,
        std=IMAGENET_STD
    )
])

# ============================================================
# VALIDATION / TEST TRANSFORM
# ============================================================
#
# No random augmentation.
# Deterministic evaluation only.
# ============================================================

eval_transform = transforms.Compose([

    transforms.Resize(288),

    transforms.CenterCrop(
        IMAGE_SIZE
    ),

    transforms.ToTensor(),

    transforms.Normalize(
        mean=IMAGENET_MEAN,
        std=IMAGENET_STD
    )
])

# ============================================================
# DATASETS
# ============================================================

train_dataset = datasets.ImageFolder(
    TRAIN_DIR,
    transform=train_transform
)

val_dataset = datasets.ImageFolder(
    VAL_DIR,
    transform=eval_transform
)

# IMPORTANT:
# We define the location but do NOT create/use the test
# DataLoader during model development.

print("=" * 75)
print("MAIZE DATA PIPELINE")
print("=" * 75)

print("\nClass mapping:")
print(train_dataset.class_to_idx)

assert (
    train_dataset.class_to_idx
    == val_dataset.class_to_idx
)

NUM_CLASSES = len(
    train_dataset.classes
)

print(
    f"\nNumber of classes: "
    f"{NUM_CLASSES}"
)

print(
    f"Training images   : "
    f"{len(train_dataset):,}"
)

print(
    f"Validation images : "
    f"{len(val_dataset):,}"
)

print(
    f"Test images       : "
    f"{sum(1 for p in TEST_DIR.rglob('*') if p.is_file()):,}"
)

# ============================================================
# TRAIN CLASS DISTRIBUTION
# ============================================================

targets = np.array(
    train_dataset.targets
)

class_counts = np.bincount(
    targets
)

print("\nTraining class distribution:")

for class_name, count in zip(
    train_dataset.classes,
    class_counts
):
    print(
        f"  {class_name:<8}: "
        f"{count:,}"
    )

# ============================================================
# WEIGHTED RANDOM SAMPLER
# ============================================================
#
# NLB and NLS have substantially fewer training examples.
#
# WeightedRandomSampler gives minority classes more chances
# to appear during an epoch without deleting majority images.
# ============================================================

class_weights = (
    len(targets)
    /
    (
        NUM_CLASSES
        * class_counts
    )
)

sample_weights = class_weights[
    targets
]

sample_weights = torch.DoubleTensor(
    sample_weights
)

generator = torch.Generator()

generator.manual_seed(
    SEED
)

train_sampler = WeightedRandomSampler(
    weights=sample_weights,
    num_samples=len(sample_weights),
    replacement=True,
    generator=generator
)

print("\nSampling weights:")

for class_name, weight in zip(
    train_dataset.classes,
    class_weights
):
    print(
        f"  {class_name:<8}: "
        f"{weight:.4f}"
    )

# ============================================================
# DATALOADERS
# ============================================================

train_loader = DataLoader(
    train_dataset,
    batch_size=BATCH_SIZE,
    sampler=train_sampler,
    num_workers=NUM_WORKERS,
    pin_memory=True,
    persistent_workers=(
        NUM_WORKERS > 0
    )
)

val_loader = DataLoader(
    val_dataset,
    batch_size=BATCH_SIZE,
    shuffle=False,
    num_workers=NUM_WORKERS,
    pin_memory=True,
    persistent_workers=(
        NUM_WORKERS > 0
    )
)

# ============================================================
# BATCH TEST
# ============================================================

images, labels = next(
    iter(train_loader)
)

print("\n" + "=" * 75)
print("BATCH TEST")
