# ============================================================
# CELL 5 — REBUILD HYBRID MODEL
# ============================================================

import torch
import torch.nn as nn

from torchvision.models import (
    resnet50,
    ResNet50_Weights
)

NUM_CLASSES = 5

EMBED_DIM = 512
NUM_HEADS = 8
NUM_TRANSFORMER_LAYERS = 4
MLP_DIM = 2048
DROPOUT = 0.20


class ResNetTransformerHybrid(nn.Module):

    def __init__(
        self,
        num_classes=5,
        embed_dim=512,
        num_heads=8,
        num_layers=4,
        mlp_dim=2048,
        dropout=0.20
    ):

        super().__init__()

        # ============================
        # ResNet50
        # ============================

        backbone = resnet50(
            weights=None
        )

        self.backbone = nn.Sequential(

            backbone.conv1,
            backbone.bn1,
            backbone.relu,
            backbone.maxpool,

            backbone.layer1,
            backbone.layer2,
            backbone.layer3,
            backbone.layer4
        )

        # ============================
        # Projection
        # ============================

        self.projection = nn.Conv2d(

            in_channels=2048,

            out_channels=embed_dim,

            kernel_size=1
        )

        # ============================
        # Positional embedding
        # ============================

        self.num_tokens = 64

        self.pos_embedding = nn.Parameter(

            torch.zeros(
                1,
                self.num_tokens,
                embed_dim
            )
        )

        # ============================
        # Transformer
        # ============================

        encoder_layer = nn.TransformerEncoderLayer(

            d_model=embed_dim,

            nhead=num_heads,

            dim_feedforward=mlp_dim,

            dropout=dropout,

            activation="gelu",

            batch_first=True,

            norm_first=True
        )

        self.transformer = nn.TransformerEncoder(

            encoder_layer,

            num_layers=num_layers
        )

        # ============================
        # Normalization
        # ============================

        self.norm = nn.LayerNorm(
            embed_dim
        )

        # ============================
        # Classifier
        # ============================

        self.classifier = nn.Sequential(

            nn.Dropout(0.30),

            nn.Linear(
                embed_dim,
                256
            ),

            nn.GELU(),

            nn.Dropout(0.20),

            nn.Linear(
                256,
                num_classes
            )
        )


    def forward(
        self,
        x
    ):

        x = self.backbone(x)

        x = self.projection(x)

        x = x.flatten(2)

        x = x.transpose(1, 2)

        x = (
            x +
            self.pos_embedding
        )

        x = self.transformer(x)

        x = self.norm(x)

        x = x.mean(dim=1)

        return self.classifier(x)


# ============================================================
# CREATE MODEL
# ============================================================

model = ResNetTransformerHybrid(

    num_classes=NUM_CLASSES,

    embed_dim=EMBED_DIM,

    num_heads=NUM_HEADS,

    num_layers=NUM_TRANSFORMER_LAYERS,

    mlp_dim=MLP_DIM,

    dropout=DROPOUT
)

model = model.to(device)

total_params = sum(
    p.numel()
    for p in model.parameters()
)

print("=" * 70)
print("HYBRID MODEL REBUILT")
print("=" * 70)

print(
    f"\nParameters : "
    f"{total_params:,}"
)

print(
    f"Device     : "
    f"{device}"
)

assert total_params == 37_333_061

print(
    "\n✓ Architecture matches "
    "Stage-1 model."
)

