# ============================================================
# VALIDATION ANALYSIS — BEST STAGE-1 CHECKPOINT
# ============================================================

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import torch

from sklearn.metrics import (
    accuracy_score,
    precision_score,
    recall_score,
    f1_score,
    balanced_accuracy_score,
    classification_report,
    confusion_matrix
)

# ------------------------------------------------------------
# Run inference on COMPLETE validation set
# ------------------------------------------------------------

all_labels = []
all_preds = []
all_probs = []

model.eval()

print("=" * 70)
print("RUNNING VALIDATION INFERENCE")
print("=" * 70)

with torch.inference_mode():

    for images, labels in val_loader:

        images = images.to(
            device,
            non_blocking=True
        )

        outputs = model(images)

        probabilities = torch.softmax(
            outputs,
            dim=1
        )

        predictions = probabilities.argmax(
            dim=1
        )

        all_labels.extend(
            labels.numpy()
        )

        all_preds.extend(
            predictions.cpu().numpy()
        )

        all_probs.extend(
            probabilities.cpu().numpy()
        )


all_labels = np.array(all_labels)
all_preds = np.array(all_preds)
all_probs = np.array(all_probs)


# ------------------------------------------------------------
# Sanity checks
# ------------------------------------------------------------

assert len(all_labels) == 1239
assert len(all_preds) == 1239
assert all_probs.shape == (1239, 5)


# ------------------------------------------------------------
# Overall metrics
# ------------------------------------------------------------

accuracy = accuracy_score(
    all_labels,
    all_preds
)

balanced_acc = balanced_accuracy_score(
    all_labels,
    all_preds
)

macro_precision = precision_score(
    all_labels,
    all_preds,
    average="macro",
    zero_division=0
)

macro_recall = recall_score(
    all_labels,
    all_preds,
    average="macro",
    zero_division=0
)

macro_f1 = f1_score(
    all_labels,
    all_preds,
    average="macro",
    zero_division=0
)


print("\n" + "=" * 70)
print("BEST STAGE-1 — VALIDATION PERFORMANCE")
print("=" * 70)

print(
    f"Accuracy           : {accuracy:.4f} "
    f"({accuracy * 100:.2f}%)"
)

print(
    f"Balanced Accuracy  : {balanced_acc:.4f} "
    f"({balanced_acc * 100:.2f}%)"
)

print(
    f"Macro Precision    : {macro_precision:.4f}"
)

print(
    f"Macro Recall       : {macro_recall:.4f}"
)

print(
    f"Macro F1           : {macro_f1:.4f}"
)

print(
    f"\nCorrect predictions: "
    f"{(all_labels == all_preds).sum():,} / {len(all_labels):,}"
)

print(
    f"Wrong predictions  : "
    f"{(all_labels != all_preds).sum():,}"
)


# ------------------------------------------------------------
# Per-class report
# ------------------------------------------------------------

class_names = val_dataset.classes

report = classification_report(
    all_labels,
    all_preds,
    target_names=class_names,
    output_dict=True,
    zero_division=0
)

class_rows = []

for class_name in class_names:

    r = report[class_name]

    class_rows.append({

        "Class": class_name,

        "Precision": r["precision"],

        "Recall": r["recall"],

        "F1": r["f1-score"],

        "Support": int(r["support"])
    })


class_df = pd.DataFrame(
    class_rows
)

print("\n" + "=" * 70)
print("PER-CLASS PERFORMANCE")
print("=" * 70)

print(
    class_df.to_string(
        index=False,
        formatters={
            "Precision": "{:.4f}".format,
            "Recall": "{:.4f}".format,
            "F1": "{:.4f}".format
        }
    )
)


# ------------------------------------------------------------
# Confusion matrix
# ------------------------------------------------------------

cm = confusion_matrix(
    all_labels,
    all_preds
)

print("\n" + "=" * 70)
print("CONFUSION MATRIX — RAW COUNTS")
print("=" * 70)

cm_df = pd.DataFrame(
    cm,
    index=[
        f"True {x}"
        for x in class_names
    ],
    columns=[
        f"Pred {x}"
        for x in class_names
    ]
)

print(cm_df)


# ------------------------------------------------------------
# Plot
# ------------------------------------------------------------

fig, ax = plt.subplots(
    figsize=(8, 7)
)

im = ax.imshow(cm)

ax.set_xticks(
    np.arange(len(class_names))
)

ax.set_yticks(
    np.arange(len(class_names))
)

ax.set_xticklabels(
    class_names
)

ax.set_yticklabels(
    class_names
)

plt.setp(
    ax.get_xticklabels(),
    rotation=45,
    ha="right",
    rotation_mode="anchor"
)

for i in range(cm.shape[0]):

    for j in range(cm.shape[1]):

        ax.text(
            j,
            i,
            str(cm[i, j]),
            ha="center",
            va="center"
        )

ax.set_xlabel(
    "Predicted Class"
)

ax.set_ylabel(
    "True Class"
)

ax.set_title(
    "Best Stage-1 Validation Confusion Matrix"
)

fig.colorbar(
    im,
    ax=ax
)

plt.tight_layout()
plt.show()


# ------------------------------------------------------------
# Specific NLB / NLS confusion
# ------------------------------------------------------------

nlb_idx = class_names.index("NLB")
nls_idx = class_names.index("NLS")

nlb_to_nls = cm[
    nlb_idx,
    nls_idx
]

nls_to_nlb = cm[
    nls_idx,
    nlb_idx
]

print("\n" + "=" * 70)
print("NLB ↔ NLS CONFUSION")
