# ============================================================
# STAGE 2 — FINE-TUNING SETUP
# Unfreeze ResNet layer4 only
# ============================================================

import torch
import torch.nn as nn

print("=" * 70)
print("STAGE 2 — FINE-TUNING SETUP")
print("=" * 70)

# ------------------------------------------------------------
# 1. Freeze complete backbone first
# ------------------------------------------------------------

for param in model.backbone.parameters():
    param.requires_grad = False


# ------------------------------------------------------------
# 2. Unfreeze ResNet layer4
#
# backbone structure:
# 0 = conv1
# 1 = bn1
# 2 = relu
# 3 = maxpool
# 4 = layer1
# 5 = layer2
# 6 = layer3
# 7 = layer4
# ------------------------------------------------------------

for param in model.backbone[7].parameters():
    param.requires_grad = True


# ------------------------------------------------------------
# 3. Projection / Transformer / Norm / Classifier remain
#    trainable
# ------------------------------------------------------------

for module in [
    model.projection,
    model.transformer,
    model.norm,
    model.classifier
]:
    for param in module.parameters():
        param.requires_grad = True


# ------------------------------------------------------------
# 4. Parameter counts
# ------------------------------------------------------------

total_params = sum(
    p.numel()
    for p in model.parameters()
)

trainable_params = sum(
    p.numel()
    for p in model.parameters()
    if p.requires_grad
)

frozen_params = (
    total_params -
    trainable_params
)

layer4_params = sum(
    p.numel()
    for p in model.backbone[7].parameters()
    if p.requires_grad
)

print(f"\nTotal parameters     : {total_params:,}")
print(f"Trainable parameters : {trainable_params:,}")
print(f"Frozen parameters    : {frozen_params:,}")

print(
    f"Trainable percentage : "
    f"{100 * trainable_params / total_params:.2f}%"
)

print(
    f"\nResNet layer4 params : "
    f"{layer4_params:,}"
)


# ------------------------------------------------------------
# 5. Loss
# Keep same label smoothing
# ------------------------------------------------------------

criterion = nn.CrossEntropyLoss(
    label_smoothing=0.10
)


# ------------------------------------------------------------
# 6. Differential learning rates
#
# Backbone gets smallest LR.
# Classification head gets largest LR.
# ------------------------------------------------------------

optimizer = torch.optim.AdamW(

    [

        # ResNet layer4
        {
            "params": model.backbone[7].parameters(),
            "lr": 1e-5
        },

        # Projection
        {
            "params": model.projection.parameters(),
            "lr": 5e-5
        },

        # Transformer
        {
            "params": model.transformer.parameters(),
            "lr": 5e-5
        },

        # LayerNorm
        {
            "params": model.norm.parameters(),
            "lr": 5e-5
        },

        # Classifier
        {
            "params": model.classifier.parameters(),
            "lr": 1e-4
        }

    ],

    weight_decay=1e-4
)


# ------------------------------------------------------------
# 7. Stage-2 configuration
# ------------------------------------------------------------

STAGE2_MAX_EPOCHS = 8

STAGE2_PATIENCE = 3

GRAD_CLIP = 1.0

STAGE2_CHECKPOINT = (
    "/content/drive/MyDrive/"
    "final_year_project/maize/checkpoints/"
    "maize_hybrid_stage2_best.pth"
)


# ------------------------------------------------------------
# 8. AMP
# ------------------------------------------------------------

scaler = torch.amp.GradScaler(
    "cuda",
    enabled=(device.type == "cuda")
)


# ------------------------------------------------------------
# 9. Verify learning rates
# ------------------------------------------------------------

print("\n" + "=" * 70)
print("LEARNING RATES")
print("=" * 70)

names = [
    "ResNet layer4",
    "Projection",
    "Transformer",
    "LayerNorm",
    "Classifier"
]

for name, group in zip(
    names,
    optimizer.param_groups
):

    print(
        f"{name:<18}: "
        f"{group['lr']:.1e}"
    )


print("\nStage-2 max epochs :", STAGE2_MAX_EPOCHS)
print("Early-stop patience:", STAGE2_PATIENCE)

print("\nCheckpoint:")
print(STAGE2_CHECKPOINT)

print("\n" + "=" * 70)
print("✓ STAGE 2 SETUP COMPLETE")
print("=" * 70)

# ============================================================
# STAGE 2 — RECREATE TRAINING PIPELINE
# ============================================================

import torch
from torchvision import datasets, transforms
from torch.utils.data import DataLoader, WeightedRandomSampler
import numpy as np

IMAGE_SIZE = 256
BATCH_SIZE = 32
NUM_WORKERS = 0

IMAGENET_MEAN = [0.485, 0.456, 0.406]
IMAGENET_STD  = [0.229, 0.224, 0.225]


# ------------------------------------------------------------
# Training augmentation
# Same morphology-preserving augmentation used in Stage 1
# ------------------------------------------------------------

train_transform = transforms.Compose([

    transforms.RandomResizedCrop(
        IMAGE_SIZE,
        scale=(0.70, 1.0),
        ratio=(0.80, 1.20)
    ),

    transforms.RandomHorizontalFlip(
        p=0.50
    ),

    transforms.RandomVerticalFlip(
        p=0.20
    ),

    transforms.RandomRotation(
        degrees=20
    ),

    transforms.RandomApply(
        [
            transforms.ColorJitter(
                brightness=0.25,
                contrast=0.25,
                saturation=0.20,
                hue=0.03
            )
        ],
        p=0.70
    ),

    transforms.RandomApply(
        [
            transforms.GaussianBlur(
                kernel_size=3,
                sigma=(0.1, 1.2)
            )
        ],
        p=0.15
    ),

    transforms.ToTensor(),

    transforms.Normalize(
        IMAGENET_MEAN,
        IMAGENET_STD
    )
])


# ------------------------------------------------------------
# Training dataset
# ------------------------------------------------------------

TRAIN_DIR = DATASET_ROOT / "train"

train_dataset = datasets.ImageFolder(
    TRAIN_DIR,
    transform=train_transform
)


# ------------------------------------------------------------
# Verify exact class mapping
# ------------------------------------------------------------

expected_mapping = {
    "Healthy": 0,
    "MLN": 1,
    "MSV": 2,
    "NLB": 3,
    "NLS": 4
}

assert train_dataset.class_to_idx == expected_mapping
assert len(train_dataset) == 5762


# ------------------------------------------------------------
# Calculate class counts
# ------------------------------------------------------------

targets = np.array(
    train_dataset.targets
)

class_counts = np.bincount(
    targets,
    minlength=len(train_dataset.classes)
)

# Inverse-frequency sample weights
class_weights = (
    len(targets) /
    (
        len(class_counts) *
        class_counts
    )
)

sample_weights = class_weights[
    targets
]


# ------------------------------------------------------------
# Weighted sampler
# ------------------------------------------------------------

sampler = WeightedRandomSampler(
    weights=torch.as_tensor(
        sample_weights,
        dtype=torch.double
    ),
    num_samples=len(sample_weights),
    replacement=True
)


# ------------------------------------------------------------
# DataLoader
# ------------------------------------------------------------

train_loader = DataLoader(

    train_dataset,

    batch_size=BATCH_SIZE,

    sampler=sampler,

    num_workers=NUM_WORKERS,

    pin_memory=True
)


# ------------------------------------------------------------
# Verification
# ------------------------------------------------------------

print("=" * 70)
print("STAGE 2 — TRAINING PIPELINE")
print("=" * 70)

print(f"\nTraining images : {len(train_dataset):,}")
print(f"Training batches: {len(train_loader)}")

print("\nClass counts:")

for i, class_name in enumerate(
    train_dataset.classes
):

    print(
        f"{class_name:<8}: "
        f"{class_counts[i]:,}"
    )


print("\nSampling weights:")

for i, class_name in enumerate(
    train_dataset.classes
):

    print(
        f"{class_name:<8}: "
        f"{class_weights[i]:.4f}"
    )


# ------------------------------------------------------------
# Test one batch
# ------------------------------------------------------------

images, labels = next(
    iter(train_loader)
)

print("\nBatch image shape :", images.shape)
print("Batch label shape :", labels.shape)

assert images.shape[1:] == (
    3,
    256,
    256
)

print("\n✓ STAGE-2 TRAINING LOADER READY")

# ============================================================
# STAGE 2 — FINE-TUNING
# ResNet layer4 + Projection + Transformer + Classifier
# ============================================================

import os
import time
import copy
import numpy as np
import torch

from tqdm.auto import tqdm

from sklearn.metrics import (
    accuracy_score,
    precision_score,
    recall_score,
    f1_score
)

# ------------------------------------------------------------
# Configuration
# ------------------------------------------------------------

MIXUP_ALPHA = 0.20
MIXUP_PROB = 0.50

STAGE2_MAX_EPOCHS = 8
STAGE2_PATIENCE = 3
GRAD_CLIP = 1.0

STAGE2_CHECKPOINT = (
    "/content/drive/MyDrive/"
    "final_year_project/maize/checkpoints/"
    "maize_hybrid_stage2_best.pth"
)

os.makedirs(
    os.path.dirname(STAGE2_CHECKPOINT),
    exist_ok=True
)


# ------------------------------------------------------------
# MixUp
# ------------------------------------------------------------

def mixup_batch(images, labels, alpha=0.20):

    lam = np.random.beta(alpha, alpha)

    batch_size = images.size(0)

    index = torch.randperm(
        batch_size,
        device=images.device
    )

    mixed_images = (
        lam * images +
        (1.0 - lam) * images[index]
    )

    labels_a = labels
    labels_b = labels[index]

    return (
        mixed_images,
        labels_a,
        labels_b,
        lam
    )


def mixup_loss(
    criterion,
    predictions,
    labels_a,
    labels_b,
    lam
):

    return (
        lam * criterion(predictions, labels_a)
        +
        (1.0 - lam) *
        criterion(predictions, labels_b)
    )


# ------------------------------------------------------------
# Baseline = best Stage-1 Macro-F1
# ------------------------------------------------------------

STAGE1_BEST_F1 = float(
    checkpoint["best_macro_f1"]
)

best_stage2_f1 = -1.0
best_stage2_epoch = 0

epochs_without_improvement = 0

stage2_history = []


print("=" * 75)
print("STAGE 2 — RESNET LAYER4 FINE-TUNING")
print("=" * 75)

print(
    f"\nStage-1 baseline Macro-F1 : "
    f"{STAGE1_BEST_F1:.4f}"
)

print(
    f"Maximum epochs            : "
    f"{STAGE2_MAX_EPOCHS}"
)

print(
    f"Early stopping patience   : "
    f"{STAGE2_PATIENCE}"
)

print(
    f"Training batches / epoch  : "
    f"{len(train_loader)}"
)

print(
    f"Validation images         : "
    f"{len(val_dataset)}"
)

print("\nStarting Stage 2...\n")


# ============================================================
# TRAINING LOOP
# ============================================================

for epoch in range(
    1,
    STAGE2_MAX_EPOCHS + 1
):

    epoch_start = time.time()

    # ========================================================
    # TRAIN
    # ========================================================

    model.train()

    # Keep frozen part of ResNet in evaluation mode.
    #
    # backbone[0:7] =
    # conv1/bn1/relu/maxpool/layer1/layer2/layer3
    #
    # layer4 remains trainable.
    for module in model.backbone[:7]:
        module.eval()

    model.backbone[7].train()

    running_loss = 0.0
    processed_samples = 0


    progress_bar = tqdm(
        train_loader,
        desc=f"Epoch {epoch}/{STAGE2_MAX_EPOCHS} [Train]",
        leave=True
    )


    for images, labels in progress_bar:

        images = images.to(
            device,
            non_blocking=True
        )

        labels = labels.to(
            device,
            non_blocking=True
        )

        optimizer.zero_grad(
            set_to_none=True
        )


        # ----------------------------------------------------
        # Random MixUp
        # ----------------------------------------------------

        use_mixup = (
            np.random.random()
            < MIXUP_PROB
        )

        if use_mixup:

            (
                model_inputs,
                labels_a,
                labels_b,
                lam
            ) = mixup_batch(
                images,
                labels,
                MIXUP_ALPHA
            )

        else:

            model_inputs = images


        # ----------------------------------------------------
        # Forward + loss with AMP
        # ----------------------------------------------------

        with torch.amp.autocast(
            device_type=device.type,
            enabled=(device.type == "cuda")
        ):

            outputs = model(
                model_inputs
            )

            if use_mixup:

                loss = mixup_loss(
                    criterion,
                    outputs,
                    labels_a,
                    labels_b,
                    lam
                )

            else:

                loss = criterion(
                    outputs,
                    labels
                )


        # ----------------------------------------------------
        # Backpropagation
        # ----------------------------------------------------

        scaler.scale(
            loss
        ).backward()

        scaler.unscale_(
            optimizer
        )

        torch.nn.utils.clip_grad_norm_(
            [
                p
                for p in model.parameters()
                if p.requires_grad
            ],
            GRAD_CLIP
        )

        scaler.step(
            optimizer
        )

        scaler.update()


        # ----------------------------------------------------
        # Statistics
        # ----------------------------------------------------

        batch_size = images.size(0)

        running_loss += (
            loss.item() *
            batch_size
        )

        processed_samples += batch_size

        progress_bar.set_postfix(
            loss=f"{running_loss / processed_samples:.4f}",
            mixup="ON" if use_mixup else "OFF"
        )


    train_loss = (
        running_loss /
        processed_samples
    )


    # ========================================================
    # VALIDATION
    # ========================================================

    model.eval()

    val_running_loss = 0.0

    val_labels = []
    val_preds = []


    val_bar = tqdm(
        val_loader,
        desc=f"Epoch {epoch}/{STAGE2_MAX_EPOCHS} [Val]",
        leave=False
    )


    with torch.inference_mode():

        for images, labels in val_bar:

            images = images.to(
                device,
                non_blocking=True
            )

            labels = labels.to(
                device,
                non_blocking=True
            )


            with torch.amp.autocast(
                device_type=device.type,
                enabled=(device.type == "cuda")
            ):

                outputs = model(
                    images
                )

                loss = criterion(
                    outputs,
                    labels
                )


            val_running_loss += (
                loss.item() *
                images.size(0)
            )

            predictions = outputs.argmax(
                dim=1
            )

            val_labels.extend(
                labels.cpu().numpy()
            )

            val_preds.extend(
                predictions.cpu().numpy()
            )


    val_loss = (
        val_running_loss /
        len(val_dataset)
    )


    # ========================================================
    # METRICS
    # ========================================================

    val_accuracy = accuracy_score(
        val_labels,
        val_preds
    )

    val_precision = precision_score(
        val_labels,
        val_preds,
        average="macro",
        zero_division=0
    )

    val_recall = recall_score(
        val_labels,
        val_preds,
        average="macro",
        zero_division=0
    )

    val_f1 = f1_score(
        val_labels,
        val_preds,
        average="macro",
        zero_division=0
    )


    epoch_minutes = (
        time.time() -
        epoch_start
    ) / 60


    stage2_history.append({

        "epoch": epoch,

        "train_loss": train_loss,

        "val_loss": val_loss,

        "val_accuracy": val_accuracy,

        "macro_precision": val_precision,

        "macro_recall": val_recall,

        "macro_f1": val_f1
    })


    # ========================================================
    # PRINT EPOCH RESULT
    # ========================================================

    print("\n" + "=" * 75)

    print(
        f"STAGE 2 — EPOCH "
        f"{epoch}/{STAGE2_MAX_EPOCHS}"
    )

    print("=" * 75)

    print(
        f"Train Loss      : "
        f"{train_loss:.4f}"
    )

    print(
        f"Val Loss        : "
        f"{val_loss:.4f}"
    )

    print(
        f"Val Accuracy    : "
        f"{val_accuracy:.4f} "
        f"({val_accuracy*100:.2f}%)"
    )

    print(
        f"Macro Precision : "
        f"{val_precision:.4f}"
    )

    print(
        f"Macro Recall    : "
        f"{val_recall:.4f}"
    )

    print(
        f"Macro F1        : "
        f"{val_f1:.4f}"
    )

    print(
        f"Time            : "
        f"{epoch_minutes:.2f} min"
    )


    # ========================================================
    # SAVE BEST STAGE-2 CHECKPOINT
    # ========================================================

    if val_f1 > best_stage2_f1:

        best_stage2_f1 = val_f1
        best_stage2_epoch = epoch

        epochs_without_improvement = 0

        torch.save({

            "stage": 2,

            "epoch": epoch,

            "model_state_dict":
                model.state_dict(),

            "optimizer_state_dict":
                optimizer.state_dict(),

            "best_macro_f1":
                best_stage2_f1,

            "stage1_baseline_macro_f1":
                STAGE1_BEST_F1,

            "class_to_idx":
                train_dataset.class_to_idx,

            "architecture":
                "ResNet50_Transformer_Hybrid",

            "image_size":
                IMAGE_SIZE,

            "history":
                stage2_history,

            "fine_tuned_backbone":
                "ResNet50_layer4",

            "learning_rates": {
                "layer4": 1e-5,
                "projection": 5e-5,
                "transformer": 5e-5,
                "norm": 5e-5,
                "classifier": 1e-4
            }

        }, STAGE2_CHECKPOINT)


        print(
            "\n✓ NEW BEST STAGE-2 CHECKPOINT"
        )

        print(
            f"  Macro-F1: "
            f"{best_stage2_f1:.4f}"
        )

        print(
            f"  Saved to: "
            f"{STAGE2_CHECKPOINT}"
        )


    else:

        epochs_without_improvement += 1

        print(
            f"\nNo Stage-2 improvement: "
            f"{epochs_without_improvement}/"
            f"{STAGE2_PATIENCE}"
        )


    # --------------------------------------------------------
    # Compare against Stage 1
    # --------------------------------------------------------

    difference = (
        val_f1 -
        STAGE1_BEST_F1
    )

    print(
        f"\nDifference vs Stage-1 baseline: "
        f"{difference:+.4f}"
    )


    # ========================================================
    # EARLY STOPPING
    # ========================================================

    if (
        epochs_without_improvement
        >= STAGE2_PATIENCE
    ):

        print("\n" + "=" * 75)

        print(
            "EARLY STOPPING TRIGGERED"
        )

        print("=" * 75)

        break


# ============================================================
# LOAD BEST STAGE-2 MODEL
# ============================================================

print("\n" + "=" * 75)
print("STAGE 2 COMPLETE")
print("=" * 75)

best_stage2_checkpoint = torch.load(
    STAGE2_CHECKPOINT,
    map_location=device,
    weights_only=False
)

model.load_state_dict(
    best_stage2_checkpoint[
        "model_state_dict"
    ]
)

model.to(device)
model.eval()


print(
    f"\nBest Stage-2 epoch    : "
    f"{best_stage2_epoch}"
)

print(
    f"Best Stage-2 Macro-F1 : "
    f"{best_stage2_f1:.4f}"
)

print(
    f"Stage-1 Macro-F1      : "
    f"{STAGE1_BEST_F1:.4f}"
)

print(
    f"Difference            : "
    f"{best_stage2_f1 - STAGE1_BEST_F1:+.4f}"
)


if best_stage2_f1 > STAGE1_BEST_F1:

    print(
        "\n✓ Stage 2 exceeded the Stage-1 "
        "validation Macro-F1."
    )

else:

    print(
        "\nStage 2 did not exceed Stage 1."
    )

print(
    "\nBest Stage-2 checkpoint:"
)

print(
    STAGE2_CHECKPOINT
)

# ============================================================
# STAGE 2 — BEST CHECKPOINT VALIDATION ANALYSIS
# ============================================================

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import torch

from sklearn.metrics import (
    accuracy_score,
    balanced_accuracy_score,
    precision_score,
    recall_score,
    f1_score,
    classification_report,
    confusion_matrix
)

