# ============================================================
# GRAD-CAM — STEP 2
# IMPLEMENT GRAD-CAM FOR HYBRID RESNET50 + TRANSFORMER
# ============================================================

import torch
import torch.nn.functional as F
import numpy as np


class GradCAM:

    def __init__(self, model, target_layer):

        self.model = model
        self.target_layer = target_layer

        self.activations = None
        self.gradients = None

        # Capture forward activations
        self.forward_handle = (
            target_layer.register_forward_hook(
                self._forward_hook
            )
        )


    def _forward_hook(self, module, inputs, output):

        self.activations = output

        # Register gradient hook directly on activation tensor
        if output.requires_grad:

            output.register_hook(
                self._save_gradient
            )


    def _save_gradient(self, grad):

        self.gradients = grad


    def generate(self, image_tensor, target_class=None):

        self.model.eval()

        self.activations = None
        self.gradients = None

        # ----------------------------------------------------
        # Gradients are required through the computation graph.
        # Model parameters remain frozen.
        # ----------------------------------------------------

        image_tensor = (
            image_tensor
            .clone()
            .detach()
            .to(device)
        )

        image_tensor.requires_grad_(True)

        # ----------------------------------------------------
        # Forward pass
        # ----------------------------------------------------

        logits = self.model(
            image_tensor
        )

        probabilities = torch.softmax(
            logits,
            dim=1
        )


        # ----------------------------------------------------
        # Choose class
        # ----------------------------------------------------

        if target_class is None:

            target_class = (
                logits.argmax(
                    dim=1
                ).item()
            )


        # ----------------------------------------------------
        # Backward from TARGET CLASS LOGIT
        # ----------------------------------------------------

        self.model.zero_grad(
            set_to_none=True
        )

        target_score = logits[
            0,
            target_class
        ]

        target_score.backward()


        # ----------------------------------------------------
        # Verify hooks captured tensors
        # ----------------------------------------------------

        if self.activations is None:

            raise RuntimeError(
                "Grad-CAM activations were not captured."
            )

        if self.gradients is None:

            raise RuntimeError(
                "Grad-CAM gradients were not captured."
            )


        # ----------------------------------------------------
        # Detach
        #
        # Shape:
        # activations = [1, 2048, 8, 8]
        # gradients   = [1, 2048, 8, 8]
        # ----------------------------------------------------

        activations = (
            self.activations
            .detach()
        )

        gradients = (
            self.gradients
            .detach()
        )


        # ----------------------------------------------------
        # Global-average-pool gradients
        #
        # One importance weight per feature channel
        # ----------------------------------------------------

        weights = gradients.mean(
            dim=(2, 3),
            keepdim=True
        )


        # ----------------------------------------------------
        # Weighted combination of feature maps
        # ----------------------------------------------------

        cam = (
            weights *
            activations
        ).sum(
            dim=1,
            keepdim=True
        )


        # Standard Grad-CAM keeps positive evidence
        cam = F.relu(cam)


        # ----------------------------------------------------
        # Resize 8×8 CAM → input resolution
        # ----------------------------------------------------

        cam = F.interpolate(
            cam,
            size=image_tensor.shape[-2:],
            mode="bilinear",
            align_corners=False
        )


        # ----------------------------------------------------
        # Normalize to [0, 1]
        # ----------------------------------------------------

        cam_min = cam.min()
        cam_max = cam.max()

        if (
            cam_max - cam_min
        ).item() > 1e-8:

            cam = (
                cam - cam_min
            ) / (
                cam_max - cam_min
            )

        else:

            cam = torch.zeros_like(
                cam
            )


        cam = (
            cam[0, 0]
            .cpu()
            .numpy()
        )


        return {
            "cam": cam,

            "logits":
                logits.detach().cpu(),

            "probabilities":
                probabilities.detach().cpu(),

            "predicted_class":
                logits.argmax(
                    dim=1
                ).item(),

            "target_class":
                target_class
        }


    def remove_hooks(self):

        self.forward_handle.remove()


# ============================================================
# INITIALIZE
# ============================================================

gradcam = GradCAM(
    model=model,
    target_layer=target_layer
)


print("=" * 75)
print("GRAD-CAM IMPLEMENTATION READY")
print("=" * 75)


# ============================================================
# SANITY TEST ON ONE TEST IMAGE
# ============================================================

