# GRAD-CAM — STEP 3
# VISUALIZE CORRECT PREDICTIONS FROM ALL 5 CLASSES
# ============================================================

import matplotlib.pyplot as plt
import numpy as np
import torch
import random


# ------------------------------------------------------------
# ImageNet de-normalization
# ------------------------------------------------------------

mean = np.array(
    [0.485, 0.456, 0.406]
).reshape(3, 1, 1)

std = np.array(
    [0.229, 0.224, 0.225]
).reshape(3, 1, 1)


def denormalize_image(tensor):

    img = (
        tensor.detach()
        .cpu()
        .numpy()
    )

    img = (
        img * std
        + mean
    )

    img = np.clip(
        img,
        0,
        1
    )

    img = np.transpose(
        img,
        (1, 2, 0)
    )

    return img


# ------------------------------------------------------------
# Find correctly predicted samples
# ------------------------------------------------------------

correct_by_class = {
    i: []
    for i in range(
        len(class_names)
    )
}


model.eval()

print("=" * 75)
print("SEARCHING FOR CORRECT EXAMPLES")
print("=" * 75)


with torch.inference_mode():

    for idx in range(
        len(test_dataset)
    ):

        image, true_label = (
            test_dataset[idx]
        )

        output = model(
            image
            .unsqueeze(0)
            .to(device)
        )

        pred = output.argmax(
            dim=1
        ).item()

        if (
            pred == true_label
            and
            len(
                correct_by_class[
                    true_label
                ]
            ) < 3
        ):

            correct_by_class[
                true_label
            ].append(idx)


        # Stop once every class has 3 examples
        if all(
            len(v) >= 3
            for v in correct_by_class.values()
        ):

            break


print("\nSelected samples:")

for class_idx, indices in (
    correct_by_class.items()
):

    print(
        f"{class_names[class_idx]:<8}: "
        f"{indices}"
    )


# ------------------------------------------------------------
# Generate Grad-CAM visualizations
# ------------------------------------------------------------

for class_idx in range(
    len(class_names)
):

    print("\n" + "=" * 75)
    print(
        f"CLASS: {class_names[class_idx]}"
    )
    print("=" * 75)


    for sample_number, idx in enumerate(
        correct_by_class[class_idx],
        start=1
    ):

        image, true_label = (
            test_dataset[idx]
        )


        # --------------------------------------------
        # Grad-CAM
        # --------------------------------------------

        result = gradcam.generate(
            image.unsqueeze(0)
        )

        cam = result["cam"]

        pred_idx = result[
            "predicted_class"
        ]

        confidence = result[
            "probabilities"
        ][0, pred_idx].item()


        # --------------------------------------------
        # Recover displayable RGB image
        # --------------------------------------------

        original = denormalize_image(
            image
        )


        # --------------------------------------------
        # Plot
        # --------------------------------------------

