# ============================================================
# GRAD-CAM — STEP 5
# IDENTIFY ALL MISCLASSIFIED TEST IMAGES
# ============================================================

import numpy as np
import pandas as pd


# ------------------------------------------------------------
# Find errors
# ------------------------------------------------------------

error_indices = np.where(
    test_labels != test_preds
)[0]

assert len(error_indices) == 28


# ------------------------------------------------------------
# Build error table
# ------------------------------------------------------------

error_records = []

for idx in error_indices:

    true_idx = int(
        test_labels[idx]
    )

    pred_idx = int(
        test_preds[idx]
    )

    pred_confidence = float(
        test_probs[
            idx,
            pred_idx
        ]
    )

    true_probability = float(
        test_probs[
            idx,
            true_idx
        ]
    )

    margin = (
        pred_confidence
        -
        true_probability
    )

    image_path = (
        test_dataset.samples[idx][0]
    )

    error_records.append({

        "Test_Index":
            int(idx),

        "True_Class":
            class_names[true_idx],

        "Predicted_Class":
            class_names[pred_idx],

        "Pred_Confidence":
            pred_confidence,

        "True_Class_Prob":
            true_probability,

        "Probability_Margin":
            margin,

        "Filename":
            image_path.split("/")[-1]
    })


error_df = pd.DataFrame(
    error_records
)


# ------------------------------------------------------------
# Sort by prediction confidence
# ------------------------------------------------------------

error_df = (
    error_df
    .sort_values(
        "Pred_Confidence",
        ascending=False
    )
    .reset_index(drop=True)
)


# ------------------------------------------------------------
