from pathlib import Path
from PIL import Image

import torch
import torch.nn.functional as F
import numpy as np

# ------------------------------------------------------------
# OOD dataset location
# ------------------------------------------------------------

OOD_ROOT = Path(
    "/content/maize_ood_validation/unknown_maize"
)

OOD_CLASSES = [
    "Common_Rust",
    "Gray_Leaf_Spot",
    "Southern_Rust",
    "Other_Unknown_Maize"
]

for cls in OOD_CLASSES:

    (
        OOD_ROOT / cls
    ).mkdir(
        parents=True,
        exist_ok=True
    )


# ------------------------------------------------------------
# Valid image extensions
# ------------------------------------------------------------

IMAGE_EXTENSIONS = {
    ".jpg",
    ".jpeg",
    ".png",
    ".bmp",
    ".webp"
}


# ------------------------------------------------------------
# Display folder status
# ------------------------------------------------------------

print("=" * 75)
print("UNKNOWN-MAIZE OOD EVALUATION DATA")
print("=" * 75)

total = 0

for cls in OOD_CLASSES:

    folder = (
        OOD_ROOT / cls
    )

    files = [
        p for p in folder.rglob("*")
        if (
            p.is_file()
            and
            p.suffix.lower()
            in IMAGE_EXTENSIONS
        )
    ]

    print(
        f"{cls:<22}: "
        f"{len(files):,}"
    )

    total += len(files)


print("-" * 40)

print(
    f"{'TOTAL':<22}: "
    f"{total:,}"
)


# ------------------------------------------------------------
# Load prototypes from previous OOD step
# ------------------------------------------------------------

prototype_path = Path(
    "/content/maize_class_prototypes_512.npy"
)

assert prototype_path.exists(), (
    "Prototype file missing. "
    "Run the prototype-analysis cell first."
)

ood_class_prototypes = torch.tensor(
    np.load(
        prototype_path
    ),
    dtype=torch.float32,
    device=device
)

ood_class_prototypes = F.normalize(
    ood_class_prototypes,
    p=2,
    dim=1
)


# ------------------------------------------------------------
# Hook model.norm
#
# Captures:
# [B, 64, 512]
# ------------------------------------------------------------

ood_norm_features = None


def ood_norm_hook(
    module,
    inputs,
    output
):

    global ood_norm_features

    ood_norm_features = (
        output.detach()
    )


# ------------------------------------------------------------
# Function for ONE image
# ------------------------------------------------------------

@torch.inference_mode()
def get_maize_ood_scores(
    image_path
):

    global ood_norm_features

    image_path = Path(
        image_path
    )

    image = Image.open(
        image_path
    ).convert("RGB")

    # IMPORTANT:
    # same deterministic transform
    # used for validation/test
    x = val_transform(
        image
    ).unsqueeze(0).to(
        device
    )

    # ----------------------------
    # Capture transformer features
    # ----------------------------

    handle = (
        model.norm
        .register_forward_hook(
            ood_norm_hook
        )
    )

    logits = model(x)

    handle.remove()

    assert (
        ood_norm_features
        is not None
    )


    # ----------------------------
    # 512-D pooled embedding
    # ----------------------------

    embedding = (
        ood_norm_features
        .mean(dim=1)
    )

    embedding = F.normalize(
        embedding,
        p=2,
        dim=1
    )


    # ----------------------------
    # Raw MSP
    # ----------------------------

    raw_probs = F.softmax(
        logits,
        dim=1
    )

    msp, pred = raw_probs.max(
        dim=1
    )


    # ----------------------------
    # Calibrated probability
    # For display only
    # ----------------------------

    calibrated_probs = F.softmax(
        logits
        /
        CALIBRATION_TEMPERATURE,
        dim=1
    )

    calibrated_confidence = (
        calibrated_probs.max(
            dim=1
        ).values
    )


    # ----------------------------
    # Energy
    # ----------------------------

    energy = (
        -torch.logsumexp(
            logits,
            dim=1
        )
    )


    # ----------------------------
    # Nearest prototype
    # ----------------------------

    similarities = (
        embedding
        @
        ood_class_prototypes.T
    )

    prototype_similarity, prototype_class = (
        similarities.max(
            dim=1
        )
    )


    return {

        "prediction_index":
            pred.item(),

        "prediction":
            class_names[
                pred.item()
            ],

        "msp":
            msp.item(),

        "calibrated_confidence":
            calibrated_confidence.item(),

        "energy":
            energy.item(),

        "prototype_similarity":
            prototype_similarity.item(),

        "nearest_prototype":
            class_names[
                prototype_class.item()
            ]
    }


# ------------------------------------------------------------
# Final status
# ------------------------------------------------------------

print("\n" + "=" * 75)

print(
    "✓ OOD SCORING PIPELINE READY"
)

print("=" * 75)

print(
    "\nFor every unknown maize image "
    "we will measure:"
)

print(
    "  • classifier prediction"
)

print(
    "  • raw MSP"
)

print(
    "  • calibrated confidence"
)

print(
    "  • energy score"
)

print(
    "  • nearest prototype similarity"
)

print(
    "\nNo rejection threshold "
    "has been selected."
)

