from pathlib import Path
import requests

OOD_ROOT = Path(
    "/content/maize_ood_validation/unknown_maize"
)

DOWNLOAD_ROOT = Path(
    "/content/maize_ood_downloads"
)

OOD_ROOT.mkdir(
    parents=True,
    exist_ok=True
)

DOWNLOAD_ROOT.mkdir(
    parents=True,
    exist_ok=True
)


# ------------------------------------------------------------
# Zenodo record
# ------------------------------------------------------------

RECORD_ID = "12609449"

API_URL = (
    f"https://zenodo.org/api/records/{RECORD_ID}"
)


print("=" * 75)
print("ZENODO SMALL MAIZE OOD DATASET")
print("=" * 75)


# ------------------------------------------------------------
# Get official file metadata
# ------------------------------------------------------------

response = requests.get(
    API_URL,
    timeout=60
)

print(
    "\nMetadata HTTP status:",
    response.status_code
)

response.raise_for_status()

record = response.json()

files = record.get(
    "files",
    []
)


print(
    f"\nFiles available: {len(files)}"
)


# ------------------------------------------------------------
# We ONLY want these two unknown diseases
# ------------------------------------------------------------

wanted_keywords = {
    "Common_Rust": [
        "Common_rust"
    ],

    "Gray_Leaf_Spot": [
        "Cercospora_leaf_spot"
    ]
}


selected = []


for ood_class, keywords in wanted_keywords.items():

    matches = []

    for file_info in files:

        filename = file_info.get(
            "key",
            ""
        )

        if any(
            keyword.lower()
            in filename.lower()

            for keyword
            in keywords
        ):

            matches.append(
                file_info
            )


    if len(matches) == 0:

        print(
            f"\n❌ Could not find file for "
            f"{ood_class}"
        )

        continue


    file_info = matches[0]

    filename = file_info["key"]

    size = file_info.get(
        "size",
        0
    )

    download_url = (
        file_info
        .get("links", {})
        .get("content")
    )


    selected.append(
        (
            ood_class,
            filename,
            size,
            download_url
        )
    )


# ------------------------------------------------------------
# Show exactly what will be downloaded
# ------------------------------------------------------------

print("\n" + "=" * 75)
print("SELECTED OOD FILES")
print("=" * 75)


total_size = 0


for (
    ood_class,
    filename,
    size,
    download_url
) in selected:

    total_size += size

    print(
        f"\nOOD class : {ood_class}"
    )

    print(
        f"File      : {filename}"
    )

    print(
        f"Size      : "
        f"{size / (1024**2):.2f} MB"
    )

    print(
        f"URL found : "
        f"{bool(download_url)}"
    )


print(
    f"\nTotal download: "
    f"{total_size / (1024**2):.2f} MB"
)


# ------------------------------------------------------------
# Download
# ------------------------------------------------------------

print("\n" + "=" * 75)
print("DOWNLOADING")
print("=" * 75)


for (
    ood_class,
    filename,
    size,
    download_url
) in selected:

    assert download_url, (
        f"No download URL for {filename}"
    )

    output_path = (
        DOWNLOAD_ROOT
        /
        filename
    )


    print(
        f"\nDownloading:"
        f"\n{filename}"
    )


    with requests.get(
        download_url,
        stream=True,
        timeout=120
    ) as r:

        r.raise_for_status()

        downloaded = 0

        with open(
            output_path,
            "wb"
        ) as f:

            for chunk in r.iter_content(
                chunk_size=1024 * 1024
            ):

                if chunk:

                    f.write(
                        chunk
                    )

                    downloaded += len(
                        chunk
                    )


    print(
        f"✓ Saved:"
        f"\n{output_path}"
    )

    print(
        f"  Downloaded: "
        f"{downloaded / (1024**2):.2f} MB"
    )


print("\n" + "=" * 75)
print("✓ DOWNLOAD COMPLETE")
print("=" * 75)

print(
    "\nNothing extracted yet."
)

print(
    "Next we will inspect the ZIP contents "
    "before putting images into the OOD folders."
)

