# ============================================================

from pathlib import Path
from collections import Counter
import zipfile
import io
import shutil

# ------------------------------------------------------------
# Paths
# ------------------------------------------------------------

OUTER_ZIP = Path(
    "/content/drive/MyDrive/final_year_project/maize/12609449.zip"
)

OOD_ROOT = Path(
    "/content/maize_ood_validation/unknown_maize"
)

COMMON_RUST_DIR = (
    OOD_ROOT / "Common_Rust"
)

GLS_DIR = (
    OOD_ROOT / "Gray_Leaf_Spot"
)

IMAGE_EXTENSIONS = {
    ".jpg",
    ".jpeg",
    ".png",
    ".bmp",
    ".webp"
}


# ------------------------------------------------------------
# Start clean for ONLY these two OOD folders
# ------------------------------------------------------------

for folder in [
    COMMON_RUST_DIR,
    GLS_DIR
]:

    if folder.exists():
        shutil.rmtree(folder)

    folder.mkdir(
        parents=True,
        exist_ok=True
    )


# ------------------------------------------------------------
# Nested ZIP mapping
# ------------------------------------------------------------

TARGETS = {

    "Corn_(maize)___Common_rust.zip":
        COMMON_RUST_DIR,

    "Corn_(maize)___Cercospora_leaf_spot.zip":
        GLS_DIR
}


print("=" * 80)
print("EXTRACTING UNKNOWN MAIZE DISEASES")
print("=" * 80)


# ------------------------------------------------------------
# Open outer ZIP
# ------------------------------------------------------------

with zipfile.ZipFile(
    OUTER_ZIP,
    "r"
) as outer:

    for nested_name, destination in TARGETS.items():

        print("\n" + "-" * 80)
        print(f"Nested ZIP : {nested_name}")
        print(f"Destination: {destination}")

        assert nested_name in outer.namelist(), (
            f"{nested_name} not found."
        )

        # Read nested ZIP into memory
        nested_bytes = outer.read(
            nested_name
        )

        with zipfile.ZipFile(
            io.BytesIO(nested_bytes),
            "r"
        ) as nested:

            bad_member = nested.testzip()

            print(
                f"ZIP integrity: "
                f"{'OK' if bad_member is None else bad_member}"
            )

            assert bad_member is None, (
                f"Corrupt member: {bad_member}"
            )

            # --------------------------------------------
            # Extract ONLY image files
            # Flatten into destination folder
            # --------------------------------------------

            image_members = [

                name

                for name in nested.namelist()

                if (
                    not name.endswith("/")
                    and
                    Path(name).suffix.lower()
                    in IMAGE_EXTENSIONS
                )
            ]

            print(
                f"Images inside: "
                f"{len(image_members):,}"
            )

            copied = 0

            for i, member in enumerate(
                image_members
            ):

                original_name = (
                    Path(member).name
                )

                # Prevent accidental filename collision
                output_name = (
                    f"{i:05d}_"
                    f"{original_name}"
                )

                output_path = (
                    destination
                    /
                    output_name
                )

                with nested.open(
                    member
                ) as src:

                    with open(
                        output_path,
                        "wb"
                    ) as dst:

                        shutil.copyfileobj(
                            src,
                            dst
                        )

                copied += 1

            print(
                f"Extracted images: "
                f"{copied:,}"
            )


# ------------------------------------------------------------
# Final audit
# ------------------------------------------------------------

print("\n" + "=" * 80)
print("OOD EXTRACTION AUDIT")
print("=" * 80)


grand_total = 0


for label, folder in [

    (
        "Common_Rust",
        COMMON_RUST_DIR
    ),

    (
        "Gray_Leaf_Spot",
        GLS_DIR
    )
]:

    files = [

        p for p in folder.iterdir()

        if (
            p.is_file()
            and
            p.suffix.lower()
            in IMAGE_EXTENSIONS
        )
    ]

    extension_counts = Counter(
        p.suffix.lower()
        for p in files
    )

    grand_total += len(files)

    print(
        f"\n{label}"
    )

    print(
        f"  Images : {len(files):,}"
    )

    print(
        f"  Folder : {folder}"
    )

    print(
        "  Types  :",
        dict(extension_counts)
    )


print("\n" + "-" * 80)

print(
    f"TOTAL OOD IMAGES: "
    f"{grand_total:,}"
)

print("\n" + "=" * 80)
print("✓ COMMON RUST + GLS EXTRACTED")
print("✓ NLB NOT EXTRACTED")
print("✓ HEALTHY NOT EXTRACTED")
print("✓ TESTING.zip NOT USED")
print("=" * 80)

# ============================================================
# MAIZE OOD — STEP 13
# IMAGE INTEGRITY + SHA256 DUPLICATE AUDIT
# ============================================================

from pathlib import Path
from PIL import Image
from collections import defaultdict, Counter
import hashlib
import pandas as pd

OOD_ROOT = Path(
    "/content/maize_ood_validation/unknown_maize"
)

OOD_FOLDERS = {
    "Common_Rust":
        OOD_ROOT / "Common_Rust",

    "Gray_Leaf_Spot":
        OOD_ROOT / "Gray_Leaf_Spot"
}

IMAGE_EXTENSIONS = {
    ".jpg",
    ".jpeg",
    ".png",
    ".bmp",
    ".webp"
}


print("=" * 80)
print("MAIZE OOD — INTEGRITY + SHA256 AUDIT")
print("=" * 80)


records = []
hash_groups = defaultdict(list)
corrupted = []


# ------------------------------------------------------------
# Scan images
# ------------------------------------------------------------

for disease, folder in OOD_FOLDERS.items():

    files = sorted([
        p for p in folder.iterdir()

        if (
            p.is_file()
            and
            p.suffix.lower()
            in IMAGE_EXTENSIONS
        )
    ])

    print(
        f"\nScanning {disease}: "
        f"{len(files):,} images"
    )

    for path in files:

        try:

            # --------------------------------------------
            # Verify image + dimensions
            # --------------------------------------------

            with Image.open(path) as img:

                img.verify()

            # Re-open after verify()
            with Image.open(path) as img:

                width, height = img.size
                mode = img.mode
                image_format = img.format


            # --------------------------------------------
            # SHA256
            # --------------------------------------------

            sha = hashlib.sha256(
                path.read_bytes()
            ).hexdigest()


            record = {

                "class":
                    disease,

                "filename":
                    path.name,

                "path":
                    str(path),

                "width":
                    width,

                "height":
                    height,

                "mode":
                    mode,

                "format":
                    image_format,

                "sha256":
                    sha
            }

            records.append(
                record
            )

            hash_groups[
                sha
            ].append(
                record
            )


        except Exception as e:

            corrupted.append(
                {
                    "class":
                        disease,

                    "path":
                        str(path),

                    "error":
                        str(e)
                }
            )


# ------------------------------------------------------------
# DataFrame
# ------------------------------------------------------------

df = pd.DataFrame(
    records
)


# ------------------------------------------------------------
# Duplicate groups
# ------------------------------------------------------------

duplicate_groups = {

    sha: group

    for sha, group
    in hash_groups.items()

    if len(group) > 1
}


duplicate_extra_files = sum(

    len(group) - 1

    for group
    in duplicate_groups.values()
)


within_class_groups = 0
cross_class_groups = 0


for group in duplicate_groups.values():

    classes = {
        item["class"]
        for item in group
    }

    if len(classes) == 1:
        within_class_groups += 1

    else:
        cross_class_groups += 1


# ------------------------------------------------------------
# Report
# ------------------------------------------------------------

print("\n" + "=" * 80)
print("INTEGRITY RESULTS")
print("=" * 80)

print(
    f"\nValid images       : "
    f"{len(records):,}"
)

print(
    f"Corrupted images   : "
    f"{len(corrupted):,}"
)

print(
    f"Unique SHA256      : "
    f"{len(hash_groups):,}"
)

print(
    f"Duplicate groups   : "
    f"{len(duplicate_groups):,}"
)

print(
    f"Redundant copies   : "
    f"{duplicate_extra_files:,}"
)

print(
    f"Within-class groups: "
    f"{within_class_groups:,}"
)

print(
    f"Cross-class groups : "
    f"{cross_class_groups:,}"
)


# ------------------------------------------------------------
# Class counts
# ------------------------------------------------------------

print("\n" + "=" * 80)
print("VALID IMAGES BY CLASS")
print("=" * 80)

if len(df) > 0:

    print(
        df["class"]
        .value_counts()
        .to_string()
    )


# ------------------------------------------------------------
# Dimension summary
# ------------------------------------------------------------

print("\n" + "=" * 80)
print("IMAGE DIMENSIONS")
print("=" * 80)

if len(df) > 0:

    for disease in OOD_FOLDERS:

        sub = df[
            df["class"] == disease
        ]

        dimension_counts = Counter(
            zip(
                sub["width"],
                sub["height"]
            )
        )

        print(
            f"\n{disease}:"
        )

        print(
            f"  Unique dimensions: "
            f"{len(dimension_counts)}"
        )

        print(
            "  Most common:"
        )

        for (
            width,
            height
        ), count in dimension_counts.most_common(10):

            print(
                f"    {width}x{height}: "
                f"{count:,}"
            )


# ------------------------------------------------------------
# Show duplicate groups if present
# ------------------------------------------------------------

if duplicate_groups:

    print("\n" + "=" * 80)
    print("EXACT DUPLICATE GROUPS")
    print("=" * 80)

    for i, (
        sha,
        group
    ) in enumerate(
        duplicate_groups.items(),
        start=1
    ):

        print(
            f"\nGroup {i} "
            f"(n={len(group)})"
        )

        for item in group:

            print(
                f"  [{item['class']}] "
                f"{item['filename']}"
            )


# ------------------------------------------------------------
# Save manifest
# ------------------------------------------------------------

MANIFEST_PATH = (
    "/content/"
    "maize_ood_integrity_manifest.csv"
)

df.to_csv(
    MANIFEST_PATH,
    index=False
)

print("\n" + "=" * 80)

print(
    f"Manifest saved:\n"
    f"{MANIFEST_PATH}"
)

print("\n✓ OOD integrity audit complete")
print("✓ No images deleted")
print("✓ Model has NOT been evaluated yet")

