# ============================================================
# STEP 18 — CROSS-DISEASE OOD FUSION
#
# Train fusion:
#   Known validation + Common Rust
# Test:
#   Known validation + GLS
#
# Then reverse:
#   Known validation + GLS
# Test:
#   Known validation + Common Rust
#
# IMPORTANT:
# This does NOT modify the maize classifier.
# ============================================================

import numpy as np
import pandas as pd

from sklearn.linear_model import LogisticRegression
from sklearn.preprocessing import StandardScaler
from sklearn.pipeline import Pipeline

from sklearn.metrics import (
    roc_auc_score,
    average_precision_score,
    roc_curve
)


# ------------------------------------------------------------
# Load known validation scores
# ------------------------------------------------------------

known_msp = np.load(
    "/content/maize_val_msp_scores.npy"
)

known_energy = np.load(
    "/content/maize_val_energy_scores.npy"
)

known_proto = np.load(
    "/content/maize_val_prototype_scores.npy"
)


# ------------------------------------------------------------
# Load unseen disease scores
# ------------------------------------------------------------

ood_df = pd.read_csv(
    "/content/maize_unseen_disease_ood_scores.csv"
)


# ------------------------------------------------------------
# Feature construction
#
# Make all features point in same direction:
#
# HIGH = more OOD-like
#
# 1-MSP        -> low confidence becomes high OOD score
# Energy       -> higher / less negative = OOD-like
# 1-Prototype  -> low similarity becomes high OOD score
# ------------------------------------------------------------

def build_features(
    msp,
    energy,
    proto
):

    return np.column_stack([

        1.0 - np.asarray(msp),

        np.asarray(energy),

        1.0 - np.asarray(proto)

    ])


known_X = build_features(
    known_msp,
    known_energy,
    known_proto
)


def dataframe_features(df):

    return build_features(

        df["msp"].to_numpy(),

        df["energy"].to_numpy(),

        df[
            "prototype_similarity"
        ].to_numpy()

    )


rust_df = ood_df[
    ood_df["true_ood_disease"]
    ==
    "Common_Rust"
].copy()


gls_df = ood_df[
    ood_df["true_ood_disease"]
    ==
    "Gray_Leaf_Spot"
].copy()


rust_X = dataframe_features(
    rust_df
)

gls_X = dataframe_features(
    gls_df
)


# ------------------------------------------------------------
# Metric function
# OOD = positive class
# ------------------------------------------------------------

def metrics(
    y_true,
    scores
):

    auroc = roc_auc_score(
        y_true,
        scores
    )

    aupr = average_precision_score(
        y_true,
        scores
    )

    fpr, tpr, thresholds = roc_curve(
        y_true,
        scores
    )

    indices = np.where(
        tpr >= 0.95
    )[0]

    if len(indices):

        idx = indices[0]

        fpr95 = fpr[idx]

        threshold = thresholds[idx]

    else:

        fpr95 = np.nan
        threshold = np.nan


    return (
        auroc,
        aupr,
        fpr95,
        threshold
    )


# ------------------------------------------------------------
# Cross-disease experiment
# ------------------------------------------------------------

def run_cross_disease(
    train_name,
    train_ood_X,
    test_name,
    test_ood_X
):

    # ----------------------------------------
    # Training data
    # ----------------------------------------

    X_train = np.vstack([
        known_X,
        train_ood_X
    ])

    y_train = np.concatenate([

        np.zeros(
            len(known_X),
            dtype=int
        ),

        np.ones(
            len(train_ood_X),
            dtype=int
        )

    ])


    # ----------------------------------------
    # Fusion model
    # ----------------------------------------

    detector = Pipeline([

        (
            "scaler",
            StandardScaler()
        ),

        (
            "logistic",
            LogisticRegression(
                class_weight="balanced",
                max_iter=2000,
                random_state=42
            )
        )

    ])


    detector.fit(
        X_train,
        y_train
    )


    # ----------------------------------------
    # Evaluate on DIFFERENT unseen disease
    # ----------------------------------------

    X_test = np.vstack([
        known_X,
        test_ood_X
    ])

    y_test = np.concatenate([

        np.zeros(
            len(known_X),
            dtype=int
        ),

        np.ones(
            len(test_ood_X),
            dtype=int
        )

    ])


    ood_probability = (
        detector.predict_proba(
            X_test
        )[:, 1]
    )


    auroc, aupr, fpr95, threshold = (
        metrics(
            y_test,
            ood_probability
        )
    )


    print("\n" + "=" * 80)

    print(
        f"TRAIN OOD: {train_name}"
    )

    print(
        f"TEST OOD : {test_name}"
    )

    print("-" * 80)

    print(
        f"AUROC      : {auroc:.4f}"
    )

    print(
        f"AUPR       : {aupr:.4f}"
    )

    print(
        f"FPR@95TPR  : "
        f"{fpr95*100:.2f}%"
    )


    return {

        "Train_OOD":
            train_name,

        "Test_OOD":
            test_name,

        "AUROC":
            auroc,

        "AUPR":
            aupr,

        "FPR95":
            fpr95,

        "Threshold":
            threshold

    }


# ------------------------------------------------------------
# Run both directions
# ------------------------------------------------------------

print("=" * 80)
print("CROSS-DISEASE OOD FUSION")
print("=" * 80)

results = []


results.append(

    run_cross_disease(

        "Common_Rust",
        rust_X,

        "Gray_Leaf_Spot",
        gls_X

    )

)


results.append(

    run_cross_disease(

        "Gray_Leaf_Spot",
        gls_X,

        "Common_Rust",
        rust_X

    )

)


# ------------------------------------------------------------
# Save
# ------------------------------------------------------------

fusion_results = pd.DataFrame(
    results
)

OUTPUT = (
    "/content/"
    "maize_cross_disease_ood_fusion.csv"
)

fusion_results.to_csv(
    OUTPUT,
    index=False
)


print("\n" + "=" * 80)
print("SUMMARY")
print("=" * 80)

print(
    fusion_results[
        [
            "Train_OOD",
            "Test_OOD",
            "AUROC",
            "AUPR",
            "FPR95"
        ]
    ].to_string(
        index=False
    )
)

print(
    f"\nSaved:\n{OUTPUT}"
)

print("\n✓ Classifier weights unchanged")
print("✓ Different disease used for OOD testing")
print("✓ No deployment threshold selected")

# ============================================================
# STEP 19 — EXTRACT 512-D OOD EMBEDDINGS
# Common Rust + Gray Leaf Spot
# ============================================================

from pathlib import Path
from PIL import Image
import numpy as np
import pandas as pd
import torch
import torch.nn.functional as F

OOD_ROOT = Path(
    "/content/maize_ood_validation/unknown_maize"
)

OOD_FOLDERS = {
    "Common_Rust": OOD_ROOT / "Common_Rust",
    "Gray_Leaf_Spot": OOD_ROOT / "Gray_Leaf_Spot"
}

IMAGE_EXTENSIONS = {
    ".jpg", ".jpeg", ".png", ".bmp", ".webp"
}

model.eval()

captured = {}

def norm_hook(module, inputs, output):
    captured["tokens"] = output.detach()

hook = model.norm.register_forward_hook(
    norm_hook
)

all_embeddings = []
all_labels = []
all_paths = []

print("=" * 80)
print("EXTRACTING OOD 512-D EMBEDDINGS")
print("=" * 80)

with torch.inference_mode():

    for disease, folder in OOD_FOLDERS.items():

        files = sorted([
            p for p in folder.iterdir()
            if p.is_file()
            and p.suffix.lower() in IMAGE_EXTENSIONS
        ])

        print(f"\n{disease}: {len(files):,}")

        for i, path in enumerate(files, 1):

            image = Image.open(path).convert("RGB")

            x = val_transform(
                image
            ).unsqueeze(0).to(device)

            _ = model(x)

            # [1, 64, 512] -> [1, 512]
            embedding = captured[
                "tokens"
            ].mean(dim=1)

            embedding = F.normalize(
                embedding,
                dim=1
            )

            all_embeddings.append(
                embedding.cpu().numpy()[0]
            )

            all_labels.append(
                disease
            )

            all_paths.append(
                str(path)
            )

            if i % 100 == 0 or i == len(files):
                print(f"  {i:,}/{len(files):,}")

hook.remove()

ood_embeddings = np.asarray(
    all_embeddings,
    dtype=np.float32
)

ood_labels = np.asarray(
    all_labels
)

ood_paths = np.asarray(
    all_paths
)

print("\n" + "=" * 80)
print("RESULT")
print("=" * 80)

print(
    "Embedding shape:",
    ood_embeddings.shape
)

print(
    "Common Rust:",
    np.sum(ood_labels == "Common_Rust")
)

print(
    "Gray Leaf Spot:",
    np.sum(ood_labels == "Gray_Leaf_Spot")
)

print(
    "Mean L2 norm:",
    np.linalg.norm(
        ood_embeddings,
        axis=1
    ).mean()
)

np.save(
    "/content/maize_ood_embeddings_512.npy",
    ood_embeddings
)

np.save(
    "/content/maize_ood_embedding_labels.npy",
    ood_labels
)

np.save(
    "/content/maize_ood_embedding_paths.npy",
    ood_paths
)

print("\nSaved:")
print("/content/maize_ood_embeddings_512.npy")
print("/content/maize_ood_embedding_labels.npy")
print("/content/maize_ood_embedding_paths.npy")

print("\n✓ OOD embeddings extracted")
print("✓ No OOD detector trained yet")
print("✓ Classifier unchanged")

# ============================================================
# STEP 20 — KNOWN-ONLY ISOLATION FOREST OOD EXPERIMENT
#
# Train:
#   Known validation embeddings ONLY
#
# Evaluate:
#   Known validation
#   Common Rust
#   Gray Leaf Spot
#
# No threshold selected.
# ============================================================

import numpy as np
import pandas as pd

from sklearn.ensemble import IsolationForest
from sklearn.metrics import (
    roc_auc_score,
    average_precision_score,
    roc_curve
)


# ============================================================
# 1. LOAD EMBEDDINGS
# ============================================================

known_X = np.load(
    "/content/maize_val_embeddings_512.npy"
).astype(np.float32)

ood_X = np.load(
    "/content/maize_ood_embeddings_512.npy"
).astype(np.float32)

ood_labels = np.load(
    "/content/maize_ood_embedding_labels.npy",
    allow_pickle=True
)


print("=" * 80)
print("DATA CHECK")
print("=" * 80)

print(
    "Known embeddings:",
    known_X.shape
)

print(
    "OOD embeddings  :",
    ood_X.shape
)

print(
    "Common Rust     :",
    np.sum(
        ood_labels == "Common_Rust"
    )
)

print(
    "Gray Leaf Spot  :",
    np.sum(
        ood_labels == "Gray_Leaf_Spot"
    )
)


# ============================================================
# 2. TRAIN ISOLATION FOREST
#
# IMPORTANT:
# contamination='auto'
#
# We are NOT asking the model to assume that a fixed
# percentage of known maize images are anomalies.
# ============================================================

detector = IsolationForest(
    n_estimators=500,
    max_samples="auto",
    contamination="auto",
    random_state=42,
    n_jobs=-1
)

print("\n" + "=" * 80)
print("TRAINING KNOWN-ONLY ISOLATION FOREST")
print("=" * 80)

detector.fit(
    known_X
)

print(
    "✓ Detector fitted using known validation embeddings only"
)


# ============================================================
# 3. GET OOD SCORES
#
# sklearn score_samples:
#     higher = more normal / ID-like
#
# We negate it:
#
#     higher = more OOD-like
# ============================================================

known_ood_score = -detector.score_samples(
    known_X
)

ood_ood_score = -detector.score_samples(
    ood_X
)


# ============================================================
# 4. METRICS
# ============================================================

def evaluate_ood(
    known_scores,
    unknown_scores
):

    y_true = np.concatenate([

        np.zeros(
            len(known_scores),
            dtype=np.int32
        ),

        np.ones(
            len(unknown_scores),
            dtype=np.int32
        )

    ])

    scores = np.concatenate([
        known_scores,
        unknown_scores
    ])


    # AUROC
    auroc = roc_auc_score(
        y_true,
        scores
    )


    # OOD = positive class
    aupr = average_precision_score(
        y_true,
        scores
    )


    # ROC
    fpr, tpr, thresholds = roc_curve(
        y_true,
        scores
    )


    # FPR @ >=95% OOD TPR
    indices = np.where(
        tpr >= 0.95
    )[0]

    if len(indices):

        idx = indices[0]

        fpr95 = fpr[idx]
        threshold95 = thresholds[idx]

    else:

        fpr95 = np.nan
        threshold95 = np.nan


    return {
        "AUROC": auroc,
        "AUPR": aupr,
        "FPR95": fpr95,
        "threshold95": threshold95
    }


# ============================================================
# 5. COMBINED OOD
# ============================================================

combined = evaluate_ood(
    known_ood_score,
    ood_ood_score
)


# ============================================================
# 6. COMMON RUST
# ============================================================

rust_mask = (
    ood_labels
    ==
    "Common_Rust"
)

rust = evaluate_ood(
    known_ood_score,
    ood_ood_score[
        rust_mask
    ]
)


# ============================================================
# 7. GLS
# ============================================================

gls_mask = (
    ood_labels
    ==
    "Gray_Leaf_Spot"
)

gls = evaluate_ood(
    known_ood_score,
    ood_ood_score[
        gls_mask
    ]
)


# ============================================================
# 8. REPORT
# ============================================================

print("\n" + "=" * 80)
print("KNOWN-ONLY ISOLATION FOREST RESULTS")
print("=" * 80)


results = {
    "Combined":
        combined,

    "Common_Rust":
        rust,

    "Gray_Leaf_Spot":
        gls
}


for name, result in results.items():

    print(
        f"\n{name}"
    )

    print("-" * 70)

    print(
        f"AUROC     : "
        f"{result['AUROC']:.4f}"
    )

    print(
        f"AUPR      : "
        f"{result['AUPR']:.4f}"
    )

    print(
        f"FPR@95TPR : "
        f"{result['FPR95']*100:.2f}%"
    )


# ============================================================
# 9. SCORE DISTRIBUTIONS
# ============================================================

print("\n" + "=" * 80)
print("ISOLATION FOREST SCORE DISTRIBUTIONS")
print("Higher = more OOD-like")
print("=" * 80)


def print_distribution(
    name,
    values
):

    print(f"\n{name}")

    print(
        f"  Min    : "
        f"{np.min(values):.6f}"
    )

    print(
        f"  P05    : "
        f"{np.percentile(values,5):.6f}"
    )

    print(
        f"  Median : "
        f"{np.median(values):.6f}"
    )

    print(
        f"  P95    : "
        f"{np.percentile(values,95):.6f}"
    )

    print(
        f"  Max    : "
        f"{np.max(values):.6f}"
    )


print_distribution(
    "Known validation",
    known_ood_score
)

print_distribution(
    "Common Rust",
    ood_ood_score[
        rust_mask
    ]
)

print_distribution(
    "Gray Leaf Spot",
    ood_ood_score[
        gls_mask
    ]
)


# ============================================================
# 10. SAVE
# ============================================================

result_df = pd.DataFrame([

    {
        "OOD_Set":
            name,

        "AUROC":
            result["AUROC"],

        "AUPR":
            result["AUPR"],

        "FPR95":
            result["FPR95"]

    }

    for name, result
    in results.items()

])


OUTPUT = (
    "/content/"
    "maize_isolation_forest_ood_results.csv"
)

result_df.to_csv(
    OUTPUT,
    index=False
)


np.save(
    "/content/maize_iforest_known_scores.npy",
    known_ood_score
)

np.save(
    "/content/maize_iforest_ood_scores.npy",
    ood_ood_score
)


print("\n" + "=" * 80)

print(
    f"Results saved:\n{OUTPUT}"
)

print("\n✓ Known-only detector experiment complete")
print("✓ Common Rust/GLS were NOT used to fit detector")
print("✓ No deployment threshold selected")
print("✓ Original classifier unchanged")

# ============================================================
# STEP 21 — EXTRACT FROZEN TRAINING EMBEDDINGS
#
# Purpose:
#   Build class distributions for Mahalanobis OOD detection.
#
# IMPORTANT:
#   - Frozen classifier
#   - Deterministic val_transform
#   - NO training augmentation
#   - NO model training
# ============================================================

from pathlib import Path
from PIL import Image

import numpy as np
import torch
import torch.nn.functional as F


TRAIN_ROOT = Path(
    "/content/Final_Maize_Dataset/train"
)

CLASS_NAMES = [
    "Healthy",
    "MLN",
    "MSV",
    "NLB",
    "NLS"
]

IMAGE_EXTENSIONS = {
    ".jpg",
    ".jpeg",
    ".png",
    ".bmp",
    ".webp"
}


# ============================================================
# 1. VERIFY TRAINING DATA
# ============================================================

print("=" * 80)
print("TRAINING DATA CHECK")
print("=" * 80)

expected_counts = {
    "Healthy": 1662,
    "MLN": 1671,
    "MSV": 1709,
    "NLB": 341,
    "NLS": 379
}

all_records = []


for class_idx, class_name in enumerate(
    CLASS_NAMES
):

    folder = (
        TRAIN_ROOT /
        class_name
    )

    files = sorted([
        p for p in folder.iterdir()

        if (
            p.is_file()
            and
            p.suffix.lower()
            in IMAGE_EXTENSIONS
        )
    ])

    print(
        f"{class_name:<10}: "
        f"{len(files):,}"
    )

    assert len(files) == expected_counts[class_name], (
        f"{class_name} count mismatch: "
        f"expected {expected_counts[class_name]}, "
        f"found {len(files)}"
    )

    for path in files:

        all_records.append(
            (
                path,
                class_idx,
                class_name
            )
        )


print("-" * 80)
print(
    f"Total: {len(all_records):,}"
)

assert len(all_records) == 5762

print("\n✓ Frozen training split verified")


# ============================================================
# 2. FEATURE HOOK
#
# model.norm output:
# [B, 64, 512]
#
# Mean pooling:
# [B, 512]
# ============================================================

captured = {}


def norm_hook(
    module,
    inputs,
    output
):

    captured["tokens"] = (
        output.detach()
    )


hook_handle = (
    model.norm.register_forward_hook(
        norm_hook
    )
)


# ============================================================
# 3. EXTRACT EMBEDDINGS
# ============================================================

model.eval()

train_embeddings = []
train_labels = []
train_paths = []


print("\n" + "=" * 80)
print("EXTRACTING TRAINING EMBEDDINGS")
print("=" * 80)


with torch.inference_mode():

    processed = 0

    for class_idx, class_name in enumerate(
        CLASS_NAMES
    ):

        class_records = [
            record

            for record in all_records

            if record[1] == class_idx
        ]

        print(
            f"\n{class_name}: "
            f"{len(class_records):,}"
        )


        for i, (
            path,
            _,
            _
        ) in enumerate(
            class_records,
            start=1
        ):

            image = Image.open(
                path
            ).convert(
                "RGB"
            )


            # IMPORTANT:
            # deterministic preprocessing
            # NOT train augmentation
            x = val_transform(
                image
            ).unsqueeze(
                0
            ).to(
                device
            )


            # Forward pass
            _ = model(
                x
            )


            # [1, 64, 512]
            tokens = captured[
                "tokens"
            ]


            # [1, 512]
            embedding = tokens.mean(
                dim=1
            )


            # Same normalization used in our
            # previous embedding experiments
            embedding = F.normalize(
                embedding,
                dim=1
            )


            train_embeddings.append(
                embedding[
                    0
                ].cpu().numpy()
            )

            train_labels.append(
                class_idx
            )

            train_paths.append(
                str(path)
            )


            processed += 1


            if (
                i % 200 == 0
                or
                i == len(class_records)
            ):

                print(
                    f"  {i:,}/"
                    f"{len(class_records):,}"
                )


hook_handle.remove()


# ============================================================
# 4. CONVERT TO ARRAYS
# ============================================================

train_embeddings = np.asarray(
    train_embeddings,
    dtype=np.float32
)

train_labels = np.asarray(
    train_labels,
    dtype=np.int64
)

train_paths = np.asarray(
    train_paths
)


