from pathlib import Path
import zipfile
import shutil
from PIL import Image


ZIP_PATH = Path(
    "/content/drive/MyDrive/final_year_project/maize/Maize.zip"
)

OUTPUT_ROOT = Path(
    "/content/maize_open_set/unknown_heldout"
)

OUTPUT_ROOT.mkdir(
    parents=True,
    exist_ok=True
)


TARGETS = {

    "Maize/Disease/03_curvularia_leaf_spot/":
        "Curvularia_Leaf_Spot",

    "Maize/Disease/04_sorghum_downy_mildew/":
        "Sorghum_Downy_Mildew"
}


IMAGE_EXTENSIONS = {
    ".jpg",
    ".jpeg",
    ".png",
    ".bmp",
    ".webp"
}


print("=" * 80)
print("EXTRACTING HELD-OUT UNKNOWN DISEASES")
print("=" * 80)


with zipfile.ZipFile(
    ZIP_PATH,
    "r"
) as zf:

    members = zf.namelist()

    for zip_folder, output_name in TARGETS.items():

        destination = (
            OUTPUT_ROOT /
            output_name
        )

        # Clean destination in case this cell is rerun
        if destination.exists():
            shutil.rmtree(destination)

        destination.mkdir(
            parents=True,
            exist_ok=True
        )


        selected = [

            name for name in members

            if (
                name.startswith(zip_folder)
                and
                not name.endswith("/")
                and
                Path(name).suffix.lower()
                in IMAGE_EXTENSIONS
            )

        ]


        print(
            f"\n{output_name}"
        )

        print(
            f"  Found in ZIP: "
            f"{len(selected)}"
        )


        for name in selected:

            filename = Path(name).name

            target_path = (
                destination /
                filename
            )

            with zf.open(name) as src:
                with open(
                    target_path,
                    "wb"
                ) as dst:

                    shutil.copyfileobj(
                        src,
                        dst
                    )


# ============================================================
# VERIFY IMAGE INTEGRITY
# ============================================================

print("\n" + "=" * 80)
print("VERIFYING HELD-OUT DATA")
print("=" * 80)


total_valid = 0
total_corrupt = 0


for output_name in TARGETS.values():

    folder = (
        OUTPUT_ROOT /
        output_name
    )

    files = sorted([

        p for p in folder.iterdir()

        if (
            p.is_file()
            and
            p.suffix.lower()
            in IMAGE_EXTENSIONS
        )

    ])


    valid = 0
    corrupt = 0


    for path in files:

        try:

            with Image.open(path) as img:
                img.verify()

            valid += 1

        except Exception as e:

            corrupt += 1

            print(
                "CORRUPT:",
                path.name,
                e
            )


    total_valid += valid
    total_corrupt += corrupt


    print(
        f"{output_name:<25} "
        f"total={len(files):>3}   "
        f"valid={valid:>3}   "
        f"corrupt={corrupt:>3}"
    )


print("-" * 80)

print(
    f"Total valid held-out images : "
    f"{total_valid}"
)

print(
    f"Total corrupted images      : "
    f"{total_corrupt}"
)


assert total_valid == 100, (
    f"Expected 100 valid images, "
    f"found {total_valid}"
)

assert total_corrupt == 0


